// monitor.js - the exported functions are the enumeration of mediated operations
let policy;                                // module-private; installed once, never handed out
class Ledger {
  #records = new Map();                    // #private: unreachable and unproxyable
  read(subject, id) {
    if (!subject?.principal) throw new Deny("no principal");          // fail closed
    if (!policy.allows(subject.principal, "read", id)) throw new Deny("no rule");
    return structuredClone(this.#records.get(id));  // never hand out the live object
  }
}
export const ledger = Object.freeze(new Ledger());                  // the only way in
export const installPolicy = (p) => { if (policy) throw new Error("already set"); policy = p; };

