function mediate(target, subject, policy) {
  const check = (act, prop) => {
    if (!policy.allows(subject.principal, act, prop)) throw new Deny(act);  // fail closed
  };
  const handler = {
    get(t, prop, recv) { check("read", prop); return Reflect.get(t, prop, recv); },
    set(t, prop, value) { check("write", prop); return Reflect.set(t, prop, value); },
    deleteProperty(t, prop) { check("delete", prop); return Reflect.deleteProperty(t, prop); },
  };
  const { proxy, revoke } = Proxy.revocable(target, handler);  // revoke() ends the grant
  return { proxy, revoke };                                    // never hand out the target
}
